def _split_cells(text: str, cut: int, style: Style, control: Control) -> tuple[Segment, Segment]:
    cell_length = cell_len(text)
    pos = 0
    cell_pos = 0

    while pos < len(text):
        char = text[pos]
        pos += 1
        char_len = cell_len(char)
        cell_pos += char_len
        if cell_pos == cut:
            return (
                _Segment(text[:pos], style, control),
                _Segment(text[pos:], style, control),
            )
        if cell_pos > cut:
            # The cut falls in the middle of a character.
            # We replace the character with spaces to maintain the width.
            num_spaces_s1 = cut - (cell_pos - char_len)
            num_spaces_s2 = cell_pos - cut
            s1_text = text[:pos - 1] + " " * num_spaces_s1
            s2_text = " " * num_spaces_s2 + text[pos:]
            return (
                _Segment(s1_text, style, control),
                _Segment(s2_text, style, control),
            )
    # This should not be reached as cut < cell_length
    return (
        _Segment(text, style, control),
        _Segment("", style, control),
    )

